{"path":"taskflow/core/slugs.py","content":""""Shared slug helper for job handlers."""

import re

_NON_SLUG_RUN = re.compile(r"[^a-z0-9]+")


def make_slug(title: str) -> str:
    """Return a lowercase, dash-separated slug built from ASCII a-z and 0-9.

    Every run of other characters becomes a single "-", and leading and
    trailing dashes are stripped. Blank input yields "".
    """
    return _NON_SLUG_RUN.sub("-", title.lower()).strip("-")
"}

